export const BODY: string = "\n<p>تصویر کراپ کرنے میں ایک منٹ سے کم لگتا ہے، جب آپ کو مراحل معلوم ہوں۔ آپ تصویر اپ لوڈ کرتے ہیں، رکھنے والے حصے کے گرد ڈبہ گھسیٹتے ہیں اور نتیجہ ڈاؤن لوڈ کرتے ہیں۔</p>\n<p>یہ طریقہ پورا عمل بتاتا ہے۔ اس میں پہلو تناسب چننا، بہتر فریمنگ کے لیے گرڈ استعمال کرنا، آؤٹ پٹ سائز جانچنا اور درست برآمد فارمیٹ چننا شامل ہے۔</p>\n<p>آخر تک آپ کسی بھی آلے پر پروفائل تصویر، بینر، اسکرین شاٹ یا دستاویز صاف کراپ کر سکیں گے۔ ڈاؤن لوڈ جانچنے تک اصل فائل رکھیں۔</p>\n<h2 id=\"before-you-start\">شروع کرنے سے پہلے: پہلے منزل چنیں</h2>\n<p>ٹول کھولنے سے پہلے طے کریں کہ کراپ شدہ تصویر کہاں رہے گی۔ پروفائل تصویر کو مربع چاہیے، بینر کو چوڑا مستطیل چاہیے اور پرنٹ کو مخصوص تناسب چاہیے۔</p>\n<p>منزل پہلو تناسب طے کرتی ہے، اور تناسب آپ کے سلیکشن ڈبے کی شکل طے کرتا ہے۔ غلط شکل سے شروع کرنے کا مطلب ہے کراپ بعد میں دوبارہ کرنا۔</p>\n<p>اصل تصویر استعمال کریں، کمپریس یا ترمیم شدہ کاپی نہیں۔ بہترین دستیاب ماخذ سے کراپ کرنے سے رکھے ہوئے پکسل زیادہ سے زیادہ تیز رہتے ہیں۔</p>\n<h2 id=\"step-by-step\">پانچ مراحل میں تصویر کراپ کریں</h2>\n<p>عمل تصویر، اسکرین شاٹ یا اسکین شدہ دستاویز کے لیے ایک جیسا ہے۔ اپ لوڈ کریں، فریم کریں، جانچیں، برآمد کریں اور ڈاؤن لوڈ کی تصدیق کریں۔</p>\n<p>فریمنگ مرحلے پر وقت لگائیں۔ اب احتیاط سے کیا گیا کراپ آپ کو دوبارہ کام کرنے سے بچاتا ہے، جب تصویر اپنی منزل میں غلط لگے۔</p>\n<ol>\n<li>تصویر ڈراپ زون میں گھسیٹ کر، اپنے آلے سے چن کر، یا Ctrl+V سے اسکرین شاٹ چسپاں کر کے اپ لوڈ کریں۔</li>\n<li>رکھنے والے حصے پر سلیکشن ڈبہ گھسیٹیں، آٹھ ہینڈل سے کسی بھی طرف یا کونے سے سائز بدلیں۔</li>\n<li>1:1، 4:3 یا 16:9 جیسا پہلو تناسب پری سیٹ چنیں، یا اپنی شکل کے لیے آزاد چھوڑ دیں۔</li>\n<li>ٹول دکھائے گئے آؤٹ پٹ پکسل ابعاد جانچیں اور تصدیق کریں کہ وہ منزل کے لیے کافی بڑے ہیں۔</li>\n<li>برآمد فارمیٹ اور کوالٹی چنیں، پھر کراپ شدہ تصویر محفوظ کرنے کے لیے Download پر کلک کریں۔</li>\n</ol>\n<p>استعمال سے پہلے ڈاؤن لوڈ شدہ فائل ایک بار کھولیں۔ تصدیق کریں کہ فریمنگ درست ہے اور کناروں پر کوئی اہم چیز کٹ نہیں گئی۔</p>\n<h2 id=\"dragging-the-selection-box\">سلیکشن ڈبہ گھسیٹنا</h2>\n<p>سلیکشن ڈبہ وہ مستطیل ہے جو آپ کا کراپ طے کرتا ہے۔ اسے منتقل کرنے کے لیے اندر گھسیٹیں، یا سائز بدلنے کے لیے آٹھ ہینڈل میں سے ایک گھسیٹیں۔</p>\n<p>کونے والے ہینڈل ایک ساتھ دو طرف سے سائز بدلتے ہیں، جو موضوع فریم کرنے کا تیز ترین طریقہ ہے۔ کنارے والے ہینڈل صرف ایک طرف ایڈجسٹ کرتے ہیں، جو باریک ایڈجسٹمنٹ کے لیے مفید ہے۔</p>\n<p>جب پہلو تناسب پری سیٹ فعال ہو تو ہینڈل ڈبے کو تناسب میں رکھتے ہیں۔ سائز بدلتے ہوئے شکل مقفل رہتی ہے، اس لیے مربع مربع ہی رہتا ہے۔</p>\n<h2 id=\"choosing-an-aspect-ratio\">پہلو تناسب پری سیٹ چننا</h2>\n<p>مربع پروفائل تصویر یا انسٹاگرام پوسٹ کے لیے 1:1 چنیں۔ گھسیٹتے ہوئے ڈبہ بالکل مربع رہتا ہے، اس لیے فریمنگ مستقل رہتی ہے۔</p>\n<p>روایتی تصویر شکل یا دستاویز کراپ کے لیے 4:3 چنیں۔ یہ چوڑائی میں اونچائی سے تھوڑا بڑا ہے، جو زیادہ تر پرنٹ شدہ تصویروں اور اسکین شدہ صفحوں کو سوٹ کرتا ہے۔</p>\n<p>چوڑے بینر، ویڈیو تھمب نیل یا پریزنٹیشن سلائیڈ کے لیے 16:9 چنیں۔ چوڑی شکل اسکرینوں پر پھیل جاتی ہے بغیر خالی جگہ چھوڑے۔</p>\n<h2 id=\"using-the-grid\">تہائی قاعدہ گرڈ استعمال کرنا</h2>\n<p>گرڈ سلیکشن ڈبے کو نو برابر حصوں میں تقسیم کرتا ہے۔ زیادہ قدرتی ترکیب کے لیے موضوع کو کسی لکیر پر یا کسی کراسنگ پوائنٹ پر رکھیں۔</p>\n<p>پورٹریٹ کے لیے آنکھیں اوپر والی افقی لکیر پر رکھیں۔ منظر کے لیے افق کو اوپر یا نیچے والی لکیر پر رکھیں، درمیان میں نہیں۔</p>\n<p>گرڈ جھکے ہوئے موضوع کو پہچاننے میں بھی مدد کرتا ہے۔ اگر افق گرڈ کے پار ترچھا چلے تو تصویر کو کراپ سے پہلے یا بعد میں سیدھا کرنے کی ضرورت ہو سکتی ہے۔</p>\n<h2 id=\"zooming-for-detail\">درست فریمنگ کے لیے زوم کرنا</h2>\n<p>جب مطلوبہ تفصیل چھوٹی ہو تو زوم کریں۔ مصنوعات کی خصوصیت، بھیڑ میں چہرہ، یا متن کی ایک لائن، سب ڈبہ رکھنے سے پہلے قریب سے دیکھنے سے فائدہ اٹھاتے ہیں۔</p>\n<p>زوم کرنے سے آؤٹ پٹ کوالٹی نہیں بدلتی۔ یہ صرف پیش نظارہ بڑا کرتا ہے تاکہ آپ سلیکشن درست رکھ سکیں، اور برآمد پھر بھی اصل پکسل استعمال کرتی ہے۔</p>\n<p>زوم کے بعد تفصیل مرکز میں لانے کے لیے تصویر گھسیٹیں، پھر اس کے گرد ڈبہ سائز کریں۔ ابعاد پڑھنے کو جانچیں کہ کراپ پھر بھی کافی بڑا ہے۔</p>\n<h2 id=\"checking-dimensions\">ڈاؤن لوڈ سے پہلے آؤٹ پٹ ابعاد جانچنا</h2>\n<p>ٹول ڈاؤن لوڈ سے پہلے بالکل آؤٹ پٹ پکسل ابعاد دکھاتا ہے۔ یہ پورے عمل میں سب سے اہم جانچ ہے، اور اس میں دو سیکنڈ لگتے ہیں۔</p>\n<p>اس عدد کو اپنی منزل کی ضرورت سے موازنہ کریں۔ پروفائل تصویر کو صرف چند سو پکسل چاہییں، جبکہ ویب سائٹ بینر کو ایک ہزار سے زیادہ چاہییں ہو سکتے ہیں۔</p>\n<p>اگر کراپ بہت چھوٹا ہو تو سلیکشن ڈبہ چوڑا کریں۔ چوڑا ڈبہ زیادہ پکسل پکڑتا ہے، جس سے منزل کو کام کرنے کے لیے زیادہ ملتا ہے۔</p>\n<h2 id=\"choosing-export-format\">برآمد فارمیٹ اور کوالٹی چننا</h2>\n<p>تصویروں کے لیے JPG چنیں۔ کوالٹی سلائیڈر فائل سائز کو تفصیل سے متوازن کرتا ہے، اور 85 سے 90 کے قریب ترتیب زیادہ تر تصویروں کو صاف رکھتی ہے۔</p>\n<p>اسکرین شاٹ، لوگو اور متن والے گرافکس کے لیے PNG چنیں۔ PNG بغیر نقصان کا ہے، اس لیے حروف کے کنارے تیز رہتے ہیں، اور ضرورت پر شفافیت محفوظ رکھتا ہے۔</p>\n<p>جب چھوٹی فائلیں اچھی کوالٹی کے ساتھ چاہییں تو WebP چنیں۔ یہ ویب تصویروں کے لیے اچھا کام کرتا ہے، اگرچہ چند پرانے نظام اب بھی اس فارمیٹ کو مسترد کرتے ہیں۔</p>\n<h2 id=\"cropping-screenshots\">اسکرین شاٹ کراپ کرنا</h2>\n<p>محفوظ کرنے والا مرحلہ چھوڑنے کے لیے اسکرین شاٹ Ctrl+V سے سیدھا چسپاں کریں۔ تصویر فوراً کراپر میں دکھائی دیتی ہے، تراشنے کے لیے تیار۔</p>\n<p>اہم حصے کے گرد ڈبہ گھسیٹیں: غلطی کا پیغام، ترتیب، یا بٹن۔ براؤزر ٹول بار، ٹاسک بار اور کوئی بھی خالی جگہ کاٹ دیں۔</p>\n<p>اسکرین شاٹ PNG کے طور پر برآمد کریں۔ بغیر نقصان کا فارمیٹ چھوٹا متن پڑھنے کے قابل رکھتا ہے، جبکہ JPG کمپریشن حروف کے کنارے دھندلا کرتی ہے اور انہیں پڑھنا مشکل بناتی ہے۔</p>\n<h2 id=\"cropping-on-mobile\">فون یا ٹیبلٹ پر کراپ کرنا</h2>\n<p>کراپر ٹچ اسکرین پر انگلی کے اشاروں کے ساتھ کام کرتا ہے۔ ڈبے کو ایک انگلی سے گھسیٹیں، اور فریمنگ قریب سے دیکھنے کی ضرورت پر چٹکی سے زوم کریں۔</p>\n<p>اپنی گیلری سے اپ لوڈ کریں یا سیدھی تصویر لیں۔ ٹول فائل کو اسی طرح سنبھالتا ہے جیسے کمپیوٹر پر، اور برآمد اختیارات ایک جیسے ہیں۔</p>\n<p>چھوٹی اسکرینیں درست فریمنگ مشکل بناتی ہیں، اس لیے ڈبہ رکھنے سے پہلے زوم کریں۔ فون پر احتیاط سے کیا گیا کراپ ڈیسک ٹاپ پر جلدی کیے گئے کراپ سے پھر بھی بہتر ہے۔</p>\n<h2 id=\"troubleshooting\">عام کراپ مسائل کا حل</h2>\n<p>اگر سلیکشن ڈبہ شکل نہیں بدلتا تو جانچیں کہ پہلو تناسب پری سیٹ مقفل تو نہیں۔ کسی بھی شکل میں ڈبہ گھسیٹنے کے لیے آزاد موڈ پر جائیں۔</p>\n<p>اگر ڈاؤن لوڈ شدہ کراپ دھندلا لگے تو سلیکشن شاید بہت چھوٹا تھا۔ اصل فائل پر واپس جائیں اور ڈبہ چوڑا کریں، یا اعلیٰ ریزولوشن ماخذ سے شروع کریں۔</p>\n<p>اگر کراپ اپنی منزل کے لیے غلط شکل کا ہو تو تناسب پری سیٹ جانچیں۔ 1:1 کراپ چوڑے بینر میں فٹ نہیں ہو گا، اور 16:9 کراپ مربع پروفائل سلاٹ میں فٹ نہیں ہو گا۔</p>\n<h2 id=\"quick-tips\">بہتر کراپ کے لیے فوری نکات</h2>\n<p>ہر بار اصل فائل سے کراپ کریں۔ پہلے سے کراپ اور محفوظ شدہ JPG کو دوبارہ کراپ کرنے سے ہر دور میں نقصان بڑھتا ہے۔</p>\n<p>موضوع کے گرد تھوڑی سانس لینے کی جگہ چھوڑ دیں۔ بغیر سر کی جگہ والا چہرہ تنگ لگتا ہے، اور کنارے کو چھونے والی مصنوعات غلطی لگتی ہے۔</p>\n<p>ڈاؤن لوڈ سے پہلے کراپ مکمل سائز پر جانچیں۔ چہرے یا متن میں زوم کریں اور تصدیق کریں کہ کوئی اہم چیز نرم یا کٹی ہوئی نہیں۔</p>\n<h2 id=\"cropping-product-photos\">مصنوعات کی تصویریں کراپ کرنا</h2>\n<p>مصنوعات کی تصویروں کو مستقل فریمنگ چاہیے، کیونکہ بے میل کراپ والی دکان کا صفحہ لاپرواہ لگتا ہے۔ ہر مصنوعات کی تصویر کو ایک ہی تناسب پر کراپ کریں تاکہ گرڈ صاف لگے۔</p>\n<p>مصنوعات کے گرد تھوڑی جگہ چھوڑ دیں۔ کناروں کو چھونے والا تنگ کراپ چیز کو تنگ دکھاتا ہے، جبکہ چھوٹا مارجن اسے سانس لینے کی جگہ دیتا ہے۔</p>\n<p>سادہ پس منظر استعمال کریں اور کناروں پر کوئی بھی بے ترتیبی کراپ کر دیں۔ سفید یا ہلکے پس منظر والی صاف مصنوعات کی تصویر خلل والی مصروف تصویر سے بہتر بکتی ہے۔</p>\n<h2 id=\"cropping-for-email\">ای میل کے لیے تصویریں کراپ کرنا</h2>\n<p>ای میل میں تصویریں چھوٹی اور درست شکل کی ہونی چاہییں، کیونکہ بڑی تصویر متن کو اسکرین سے ہٹا سکتی ہے یا پیغام کو سست لوڈ کر سکتی ہے۔</p>\n<p>منسلک کرنے سے پہلے تصویر کو اہم حصے پر کراپ کریں۔ چھوٹی تفصیل والا مکمل اسکرین شاٹ ای میل میں بیکار ہے، جبکہ تفصیل کا تنگ کراپ فوراً واضح ہوتا ہے۔</p>\n<p>ای میل تصویریں تصویروں کے لیے JPG اور اسکرین شاٹ کے لیے PNG کے طور پر برآمد کریں۔ چھوٹا فائل سائز ای میل کو ہلکا رکھتا ہے، اور درست فارمیٹ مواد کو پڑھنے کے قابل رکھتا ہے۔</p>\n<h2 id=\"cropping-and-accessibility\">کراپ اور رسائی</h2>\n<p>اچھا کراپ سب کی مدد کرتا ہے، مگر ان لوگوں کے لیے سب سے اہم ہے جو تصویریں بڑے سائز میں دیکھتے ہیں یا اسکرین میگنفائر استعمال کرتے ہیں۔ اہم مواد کا تنگ کراپ خلل والے چوڑے شاٹ سے زیادہ آسان ہے۔</p>\n<p>جب آپ ڈایاگرام یا چارٹ کراپ کریں تو لیبل اور لیجنڈ فریم کے اندر رکھیں۔ لیبل کے بغیر چارٹ بے معنی ہے، چاہے کراپ کتنا ہی تیز ہو۔</p>\n<p>ہدایتی تصویروں کے لیے ایک وقت میں ایک مرحلہ کراپ کریں۔ فی مرحلہ ایک واضح کراپ پورا عمل دکھانے والی ایک بڑی تصویر سے زیادہ آسان ہے۔</p>\n<h2 id=\"saving-crop-presets\">دہرائے جانے والے کراپ سے وقت بچانا</h2>\n<p>اگر آپ اکثر ایک ہی طرح کی تصویر کراپ کرتے ہیں تو اس کے گرد عادت بنائیں۔ ہر بار ایک ہی تناسب پری سیٹ، ایک ہی برآمد فارمیٹ اور ایک ہی نام دینے کا انداز استعمال کریں۔</p>\n<p>مستقل معمول ہر کراپ پر منٹ بچاتا ہے۔ آپ تناسب اور فارمیٹ کا فیصلہ ہر بار نئے سرے سے کرنا چھوڑ دیتے ہیں، اور سوچے بغیر صاف کراپ بنانا شروع کر دیتے ہیں۔</p>\n<p>اپنے پلیٹ فارم کو چاہیے تناسب کا نوٹ رکھیں۔ اپنی میز پر چھوٹی فہرست، جیسے پروفائل 1:1 اور بینر 16:9، ہر کراپ سیشن سے اندازہ ختم کر دیتی ہے۔</p>\n<p>تناسب رہنمائی کے لیے <a href=\"/ur/blog/tasveer-crop-ratios-wazahat/\">Crop Ratios Explained: 1:1, 4:3, 16:9 and Custom</a> پڑھیں۔ مکمل جائزے کے لیے <a href=\"/ur/blog/tasveer-crop-karein-rehnumai/\">Image Cropper: Complete Guide</a> دیکھیں، اور اگر تصویر جھکی ہوئی ہو تو پہلے <a href=\"/ur/tasveer-ghumayein-ultayein/\">Rotate and Flip ٹول</a> سے سیدھا کریں۔</p>\n";

